xpath.script:
                document.addEventListener("DOMContentLoaded", function () {
                    // Rename 'Name' / 'Your Name' label to 'Username'
                    var labels = document.querySelectorAll("label");
                    for (var i = 0; i < labels.length; i++) {
                        var txt = labels[i].textContent.trim().toLowerCase();
                        if (txt === 'your name' || txt === 'name') {
                            labels[i].textContent = "Username";
                        }
                    }

                    var realEmail = "";
                    var realLogin = "";

                    // Make Username input readonly and ensure it displays user login
                    var nameInput = document.querySelector("input[name='name']");
                    if (nameInput) {
                        if (realLogin) {
                            nameInput.value = realLogin;
                        }
                        nameInput.readOnly = true;
                        nameInput.style.setProperty("background-color", "#f1f5f9", "important");
                        nameInput.style.setProperty("cursor", "not-allowed", "important");
                        nameInput.style.setProperty("color", "#475569", "important");
                    }

                    // Make Email input readonly and ensure it displays real user email
                    var loginInput = document.querySelector("input[name='login']");
                    if (loginInput) {
                        if (realEmail) {
                            loginInput.value = realEmail;
                        }
                        loginInput.readOnly = true;
                        loginInput.style.setProperty("background-color", "#f1f5f9", "important");
                        loginInput.style.setProperty("cursor", "not-allowed", "important");
                        loginInput.style.setProperty("color", "#475569", "important");
                    }

                    // Remove/hide 'Already have an account?' link completely
                    var links = document.querySelectorAll(".oe_signup_form a, form a");
                    for (var j = 0; j < links.length; j++) {
                        var ltxt = links[j].textContent.trim().toLowerCase();
                        if (ltxt.indexOf("already have an account") !== -1 || ltxt.indexOf("back to login") !== -1 || (links[j].getAttribute("href") && links[j].getAttribute("href").indexOf("/web/login") !== -1)) {
                            links[j].style.setProperty("display", "none", "important");
                        }
                    }
                });
